CREATE TABLE IF NOT EXISTS platform_migrations(id VARCHAR(64) PRIMARY KEY);
CREATE TABLE IF NOT EXISTS countries(code CHAR(2) PRIMARY KEY,name VARCHAR(100) NOT NULL,currency_code CHAR(3) NOT NULL,active BOOLEAN NOT NULL DEFAULT 1,FOREIGN KEY(currency_code) REFERENCES currencies(code));
CREATE TABLE IF NOT EXISTS ai_models(id VARCHAR(64) PRIMARY KEY,owner_id VARCHAR(64) NULL,company ENUM('OPENAI','GEMINI') NOT NULL,label VARCHAR(100) NOT NULL,model VARCHAR(100) NOT NULL,key_cipher TEXT NOT NULL,key_last_four CHAR(4) NOT NULL,active BOOLEAN NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(owner_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS saved_cards(id VARCHAR(64) PRIMARY KEY,user_id VARCHAR(64) NOT NULL,label VARCHAR(80) NOT NULL,last_four CHAR(4) NOT NULL,expiry CHAR(5) NOT NULL,demo_token VARCHAR(20) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS team_members(user_id VARCHAR(64) PRIMARY KEY,department VARCHAR(100) NOT NULL,designation VARCHAR(100) NOT NULL,phone VARCHAR(40) NOT NULL DEFAULT '',portfolio VARCHAR(300) NOT NULL DEFAULT '',is_ceo BOOLEAN NOT NULL DEFAULT 0,published BOOLEAN NOT NULL DEFAULT 0,display_order INT NOT NULL DEFAULT 0,FOREIGN KEY(user_id) REFERENCES users(id));
